// Apply peripheral-register labels and data types from a tools/ghidra/sfr_<chip>.tsv to the current program:
// sfr_rx651.tsv (MAIN, T23a), sfr_rza1h.tsv (DISPLAY, T23b), sfr_rt685.tsv / sfr_rt685_hifi4.tsv (IFDSP M33 / HiFi4, T23b).
// Headless usage (from the repo root), after ApplyNames.java (it never renames a user label that is already there):
//   tools/ghidra-headless.sh "$PWD/ghidra" FT710_MAIN -process FT-710_MAIN_V0112.bin -noanalysis \
//     -scriptPath tools/ghidra -postScript ApplySfr.java tools/ghidra/sfr_rx651.tsv [labels]
// The TSVs are generated by tools/sfr_table.py from the vendors' manuals and SVD (columns are documented there).
// For each register whose address is in program memory (rows outside the setup script's blocks are skipped and counted
// as "not in memory": the RX651 option-setting memory at 0xFE7F5D00.., the RZ/A1H debug registers at 0xFC000000..,
// the RT685 secure alias and Arm SCS on the HiFi4, which has none):
//   * label MODULE_SYMBOL (e.g. IWDT_IWDTCR). primary=1 rows make it the primary label unless a user label is already
//     primary there; alias rows (SMCI0_SMR next to SCI0_SMR) become secondary labels.
//   * data type byte/word/dword/qword (byte[16] for 128-bit) for primary rows without an overlap, so the decompiler
//     prints IWDT_IWDTCR = 0x3350 instead of DAT_00088032 = 0x3350. Only undefined data is replaced; existing defined
//     data is left alone and counted. Pass "labels" as the second argument to skip the types.
//   * EOL comment "<register name> (HWM s<section>)" where no EOL comment exists (rows with section '-' are not from a
//     manual section, e.g. EXTRA or SVD rows, and carry their source in the name).
// Idempotent: a second run changes nothing. Removing a row from the TSV does not remove its label (rebuild the
// program with tools/bootstrap.sh FORCE=1 for that).
// @category FT710
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.data.*;
import ghidra.program.model.listing.CodeUnit;
import ghidra.program.model.listing.Data;
import ghidra.program.model.listing.Listing;
import ghidra.program.model.mem.Memory;
import ghidra.program.model.symbol.SourceType;
import ghidra.program.model.symbol.Symbol;
import ghidra.program.model.symbol.SymbolTable;

import java.nio.file.Files;
import java.nio.file.Paths;

public class ApplySfr extends GhidraScript {
    private DataType typeFor(int bits) {
        switch (bits) {
            case 8: return ByteDataType.dataType;
            case 16: return WordDataType.dataType;
            case 32: return DWordDataType.dataType;
            case 64: return QWordDataType.dataType;
            default: return new ArrayDataType(ByteDataType.dataType, bits / 8, 1);
        }
    }

    @Override
    protected void run() throws Exception {
        String[] args = getScriptArgs();
        boolean types = !(args.length > 1 && args[1].equals("labels"));
        Memory mem = currentProgram.getMemory();
        Listing listing = currentProgram.getListing();
        SymbolTable st = currentProgram.getSymbolTable();
        int labels = 0, typed = 0, keptData = 0, unmapped = 0, keptPrimary = 0, bad = 0;
        for (String line : Files.readAllLines(Paths.get(args[0]))) {
            if (line.isBlank() || line.startsWith("#")) continue;
            String[] p = line.split("\t", -1);
            if (p.length < 10) { printerr("ApplySfr: short row: " + line); bad++; continue; }
            Address a = toAddr(Long.parseLong(p[0], 16));
            String label = p[1];
            int bits = Integer.parseInt(p[4]);
            boolean primary = p[6].equals("1"), overlap = p[7].equals("1");
            if (!mem.contains(a)) { unmapped++; continue; }

            Symbol cur = st.getPrimarySymbol(a);
            boolean userPrimary = cur != null && cur.getSource() == SourceType.USER_DEFINED && !cur.getName().equals(label);
            Symbol s = null;
            for (Symbol x : st.getSymbols(a)) if (x.getName().equals(label)) s = x;
            if (s == null) {
                s = createLabel(a, label, false, SourceType.IMPORTED);
                labels++;
            }
            if (primary) {
                if (userPrimary) keptPrimary++;
                else if (!s.isPrimary()) s.setPrimary();
            }

            if (types && primary && !overlap) {
                DataType dt = typeFor(bits);
                Data d = listing.getDefinedDataAt(a);
                if (d == null || !d.isDefined()) {
                    try {
                        listing.clearCodeUnits(a, a.add(dt.getLength() - 1), false);
                        listing.createData(a, dt);
                        typed++;
                    } catch (Exception e) {
                        printerr("ApplySfr: no type at " + a + " for " + label + ": " + e.getMessage());
                        bad++;
                    }
                } else if (!d.getDataType().isEquivalent(dt)) {
                    keptData++;
                }
            }
            if (primary && listing.getComment(CodeUnit.EOL_COMMENT, a) == null) {
                listing.setComment(a, CodeUnit.EOL_COMMENT, p[8].equals("-") ? p[9] : p[9] + " (HWM s" + p[8] + ")");
            }
        }
        println("ApplySfr: " + labels + " labels added, " + typed + " typed, " + keptData + " kept existing data, "
                + keptPrimary + " kept a user primary label, " + unmapped + " not in memory, " + bad + " failed");
    }
}
